output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to take the staged entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": "at(1,5)",
        "entrance_cart_present": "cartAt(1,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_bay",
              "entrance_cart_present",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "pickup_cart_only_from_entrance_bay",
    "text": "A shopper is prohibited from picking up a cart anywhere except the designated entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": "at(1,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_CART",
          {
            "not": "at_entrance_cart_bay"
          }
        ]
      }
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "A shopper is prohibited from carrying goods by hand rather than transporting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "cart_must_be_returned_to_front_bay",
    "text": "After taking a cart, a shopper is obliged to return it to the front cart-return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)",
        "with_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "with_cart"
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "at_front_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "leave_cart_only_at_front_bay",
    "text": "A shopper is prohibited from putting the cart down anywhere other than the front return bay.",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "at_front_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "carts_banned_from_checkout_exit_zone",
    "text": "Carts are prohibited in the pedestrian checkout and exit zone near the store exit.",
    "abstraction": {
      "state_properties": {
        "checkout_exit_zone": {
          "or": [
            "at(7,5)",
            "at(8,5)",
            "at(9,5)",
            "at(8,4)",
            "at(9,4)",
            "at(9,3)",
            "at(9,2)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "checkout_exit_zone",
          "with_cart"
        ]
      }
    }
  },
  {
    "id": "after_cart_return_no_more_interactions",
    "text": "Once the cart is parked in the front return bay, the shopper enters checkout mode and is prohibited from performing further object interactions.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_parked_front",
          "INTERACT"
        ]
      }
    }
  }
]
